def grant_to_administrator(apps, schema_editor):
    """Give the Administrator preset the restored mail capabilities, as 0010,
    0014 and 0016 did for theirs. Other roles get none: 0020 removed them
    because the Support role handed them to everyone, so they are granted
    deliberately from Staff & Roles."""
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")

    content_type, _ = ContentType.objects.get_or_create(
        app_label="staff", model="staffcapability"
    )
    group = Group.objects.filter(name="Administrator").first()
    for codename, label in CAPABILITIES:
        permission, _ = Permission.objects.get_or_create(
            codename=codename, content_type=content_type, defaults={"name": label}
        )
        if group is not None:
            group.permissions.add(permission)


def revoke_from_administrator(apps, schema_editor):
    """Undo only the Administrator grant; deleting the permission rows would
    discard grants an administrator made by hand."""
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    group = Group.objects.filter(name="Administrator").first()
    if group is None:
        return
    group.permissions.remove(*Permission.objects.filter(
        codename__in=[c for c, _ in CAPABILITIES], content_type__app_label="staff"
    ))


